import { getFontVariables } from './lib/fonts';
import "./globals.css";
import "./styles/grid-background.css";
import "./styles/speech-playground.css";
import "./styles/pricing-section.css";
import "./styles/navigation-responsive.css";
import { ClerkProvider, ClerkLoaded, ClerkLoading } from "@clerk/nextjs";
import Loader from "./components/Loader";
import NavigationBar from "./components/NavigationBar";
import FooterWrapper from "./components/FooterWrapper";
import dynamic from "next/dynamic";
import { getBodyAttributes } from './components/server/VideoSvdAttributes';

// Use the client component wrapper
const CanvasCursorWrapper = dynamic(() => import('./components/client/canvas-cursor-wrapper'));
const VideoSvdProvider = dynamic(() => import('./components/client/VideoSvdProvider'));



// Fonts are now imported from lib/fonts.js

export const metadata = {
  title: 'Orator Path',
  description: 'Improve your public speaking skills',
};

export default async function RootLayout({ children }) {
  // This is a server component, so we need to use a Client Component wrapper for pathname
  // Get body attributes from server component to ensure consistency with client-side rendering
  const bodyAttributes = await getBodyAttributes();

  return (
    <html lang="en" className={getFontVariables()}>
      <body className="min-h-screen bg-black text-white" {...bodyAttributes}>
        <VideoSvdProvider />
        <ClerkProvider>
          <div className="relative min-h-screen flex flex-col">
            <div className="fixed inset-0 -z-10 pattern-bg"></div>
            <NavigationBar />
            <ClerkLoading>
              <Loader />
            </ClerkLoading>
            <ClerkLoaded>
              <main className="relative z-10 flex-grow">
                {children}
              </main>
              <div className="z-10">
                <FooterWrapper />
              </div>
              <CanvasCursorWrapper />
            </ClerkLoaded>
          </div>
        </ClerkProvider>
      </body>
    </html>
  );
}

