import { Geist, Geist_Mono, Inter, Space_Grotesk, Cinzel_Decorative, Noto_Serif } from "next/font/google";
import localFont from 'next/font/local';

// Google Fonts
export const cinzelDecorative = Cinzel_Decorative({
  variable: "--font-cinzel-decorative",
  subsets: ["latin"],
  display: "swap",
  weight: ["400", "700", "900"],
});

export const notoSerif = Noto_Serif({
  variable: "--font-noto-serif",
  subsets: ["latin"],
  display: "swap",
  weight: ["400", "700"],
});

export const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
  display: "swap",
});

export const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
  display: "swap",
});

export const inter = Inter({
  subsets: ["latin"],
  variable: "--font-inter",
  display: "swap",
});

export const spaceGrotesk = Space_Grotesk({
  subsets: ["latin"],
  variable: "--font-space-grotesk",
  display: "swap",
});

// Local Fonts
export const nathan = localFont({
  src: '../fonts/Nathan.otf',
  variable: '--font-nathan',
  display: 'swap',
});



// Helper to combine all font variables into a single className string
export function getFontVariables() {
  return `${geistSans.variable} ${geistMono.variable} ${inter.variable} ${spaceGrotesk.variable} ${nathan.variable} ${cinzelDecorative.variable} ${notoSerif.variable}`;
}
